From f3af48221a3c64674d7e66aaa5f935b989134454 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:21:09 +0100
Subject: [PATCH] applets/kicker: Put a runner's requested query in the search
 field

Kicker and the Application Dashboard ignored a runner's request to set
the search text and closed anyway, so calculator results did nothing.
Set the text on request, and only close when an item was launched.

BUG: 500913
---
 applets/kicker/DashboardRepresentation.qml | 7 +++++++
 applets/kicker/ItemAbstractDelegate.qml    | 6 ++++--
 applets/kicker/ItemGridView.qml            | 3 +--
 applets/kicker/MenuRepresentation.qml      | 7 +++++++
 4 files changed, 19 insertions(+), 4 deletions(-)

diff --git a/applets/kicker/DashboardRepresentation.qml b/applets/kicker/DashboardRepresentation.qml
index b0a6c9500c..db54d29681 100644
--- a/applets/kicker/DashboardRepresentation.qml
+++ b/applets/kicker/DashboardRepresentation.qml
@@ -266,6 +266,13 @@ Kicker.DashboardWindow {
                 text = "";
             }

+            Connections {
+                target: root.runnerModel
+                function onRequestUpdateQuery(query: string) : void {
+                    searchField.text = query;
+                }
+            }
+
             Keys.priority: Keys.AfterItem
             Keys.onTabPressed: {
                 if (root.runnerModel.count) {
diff --git a/applets/kicker/ItemAbstractDelegate.qml b/applets/kicker/ItemAbstractDelegate.qml
index 3e0801e1ac..738f59fd09 100644
--- a/applets/kicker/ItemAbstractDelegate.qml
+++ b/applets/kicker/ItemAbstractDelegate.qml
@@ -45,8 +45,10 @@ PlasmaComponents3.ItemDelegate {
         onTriggered: source => {
             if (item.dragActive) { return }
             if (!item.hasChildren) {
-                item.baseModel.trigger(item.index, "", null);
-                item.interactionConcluded()
+                // false when nothing was launched, e.g. the calculator put its result in the search field
+                if (item.baseModel.trigger(item.index, "", null)) {
+                    item.interactionConcluded()
+                }
             } else {
                 item.openCategory(source instanceof KeyEvent)
             }
diff --git a/applets/kicker/ItemGridView.qml b/applets/kicker/ItemGridView.qml
index 4db87e24c9..2ce9a1fe37 100644
--- a/applets/kicker/ItemGridView.qml
+++ b/applets/kicker/ItemGridView.qml
@@ -336,8 +336,7 @@ FocusScope {
             Keys.onRightPressed: event => handleLeftRightArrow(event)
             Keys.onEnterPressed: Keys.returnPressed()
             Keys.onReturnPressed: {
-                if (gridView.model.trigger) {
-                    gridView.model.trigger(currentIndex, "", null)
+                if (gridView.model.trigger && gridView.model.trigger(currentIndex, "", null)) {
                     itemGrid.interactionConcluded()
                 }
             }
diff --git a/applets/kicker/MenuRepresentation.qml b/applets/kicker/MenuRepresentation.qml
index f3593a1e37..3d9bb5d38b 100644
--- a/applets/kicker/MenuRepresentation.qml
+++ b/applets/kicker/MenuRepresentation.qml
@@ -515,6 +515,13 @@ PlasmaComponents3.ScrollView {
             }
         }

+        Connections {
+            target: root.runnerModel
+            function onRequestUpdateQuery(query: string) : void {
+                searchField.text = query;
+            }
+        }
+
         Keys.priority: Keys.AfterItem // arrow keys should move cursor first
         Keys.onUpPressed: event => handleUpDownArrow(event)
         Keys.onDownPressed: event => handleUpDownArrow(event)
-- 
2.53.0

From 4766825ae9a7b4017797c42830fa76e8ee19462b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:21:09 +0100
Subject: [PATCH] applets/kicker: Forward runners' requests to change the
 search text

Running a calculator result asks to replace the search text with it, but
RunnerModel never connected that request, so Kickoff and Kicker did
nothing. Forward queryStringChangeRequested to requestUpdateQuery.

BUG: 500913
---
 applets/kicker/runnermatchesmodel.cpp | 1 -
 applets/kicker/runnermatchesmodel.h   | 2 --
 applets/kicker/runnermodel.cpp        | 2 ++
 3 files changed, 2 insertions(+), 3 deletions(-)

diff --git a/applets/kicker/runnermatchesmodel.cpp b/applets/kicker/runnermatchesmodel.cpp
index 8c1ea5790c..ae2dc022d1 100644
--- a/applets/kicker/runnermatchesmodel.cpp
+++ b/applets/kicker/runnermatchesmodel.cpp
@@ -57,7 +57,6 @@ RunnerMatchesModel::RunnerMatchesModel(const QString &runnerId, const std::optio
             }
         }
     }
-    connect(runnerManager(), &KRunner::RunnerManager::requestUpdateQueryString, this, &RunnerMatchesModel::requestUpdateQueryString);
 }

 AbstractModel *RunnerMatchesModel::favoritesModel() const
diff --git a/applets/kicker/runnermatchesmodel.h b/applets/kicker/runnermatchesmodel.h
index 092a2b0c3d..3b407025df 100644
--- a/applets/kicker/runnermatchesmodel.h
+++ b/applets/kicker/runnermatchesmodel.h
@@ -66,8 +66,6 @@ public:
         return AbstractModel::staticRoleNames();
     }

-    Q_SIGNAL void requestUpdateQueryString(const QString &term);
-
 private:
     AbstractModel *m_favoritesModel = nullptr;
     const QString m_runnerId;
diff --git a/applets/kicker/runnermodel.cpp b/applets/kicker/runnermodel.cpp
index 73d6f95d27..7a68c79a4a 100644
--- a/applets/kicker/runnermodel.cpp
+++ b/applets/kicker/runnermodel.cpp
@@ -324,6 +324,8 @@ void RunnerModel::initializeModels()
                 Q_EMIT queryingChanged();
             }
         });
+        // e.g. the calculator puts its result in the search field when run
+        connect(model, &RunnerMatchesModel::queryStringChangeRequested, this, &RunnerModel::requestUpdateQuery);
         connect(model->runnerManager(), &KRunner::RunnerManager::queryFinished, this, [this]() {
             Q_EMIT anyRunnerFinished();
             if (!m_resultsPresent) {
-- 
